// A tiny egress proxy: HTTPS only, one site on the allow-list, one log line per request.
import { createServer } from "node:http";
import { connect } from "node:net";

const ALLOW = new Set(["registry.npmjs.org"]); // stands for our internal package mirror
const log = (verdict, req) => console.log(`${new Date().toISOString()} ${verdict} ${req.socket.remoteAddress} ${req.method} ${req.url}`);

const proxy = createServer((req, res) => { log("DENIED", req); res.writeHead(403).end(); }); // plain HTTP: never
proxy.on("connect", (req, client, head) => {
  const [host, port = "443"] = req.url.split(":");
  if (!ALLOW.has(host)) { log("DENIED", req); return client.end("HTTP/1.1 403 Forbidden\r\n\r\n"); }
  log("ALLOWED", req);
  const upstream = connect(Number(port), host, () => {
    client.write("HTTP/1.1 200 Connection Established\r\n\r\n");
    upstream.write(head);
    upstream.pipe(client).on("error", () => {});
    client.pipe(upstream).on("error", () => {});
  });
  upstream.on("error", () => client.destroy());
  client.on("error", () => upstream.destroy());
});
proxy.listen(3128, () => console.log("proxy listening on 3128"));
EOF

