// The alert rule: more than 5 blocked requests from one source in 5 minutes.
import { readFileSync } from "node:fs";

const since = Date.now() - 5 * 60 * 1000;
const denied = {};
for (const line of readFileSync(0, "utf8").split("\n")) {
  const [time, verdict, source] = line.split(" ");
  if (verdict === "DENIED" && Date.parse(time) > since) denied[source] = (denied[source] ?? 0) + 1;
}
const loud = Object.entries(denied).filter(([, n]) => n > 5);
for (const [source, n] of loud) console.log(`ALERT: ${n} blocked requests from ${source} in 5 minutes. Possible prompt injection: find the run.`);
if (!loud.length) console.log("no alert");
